    def _make_mswp_pairs(new_fid: int, edid: str, pairs: list[tuple[str, str]]) -> bytes:
        subs = bytearray(pack_zstr("EDID", edid))
        seen_bnam: set[str] = set()
        for bnam, snam in pairs:
            for b_var in (bnam, bnam.lower()):
                if b_var not in seen_bnam:
                    seen_bnam.add(b_var)
                    subs.extend(pack_zstr("BNAM", b_var))
                    subs.extend(pack_zstr("SNAM", snam))
        return pack_record("MSWP", new_fid, bytes(subs))

