    def make_custom_omni_light(
        new_fid: int, edid: str, radius: int, rgb: tuple[int, int, int], fade: float
    ) -> bytes:
        src_raw = tpl["ligh_omni_ns"][3]
        out_l = bytearray(pack_zstr("EDID", edid))
        sp_l = 0
        while sp_l + 6 <= len(src_raw):
            st_l = src_raw[sp_l : sp_l + 4].decode("ascii", "ignore")
            ss_l = struct.unpack_from("<H", src_raw, sp_l + 4)[0]
            sv_l = bytearray(src_raw[sp_l + 6 : sp_l + 6 + ss_l])
            if st_l == "EDID":
                pass
            elif st_l == "DATA" and ss_l >= 12:
                struct.pack_into("<I", sv_l, 4, radius)
                sv_l[8] = rgb[0]
                sv_l[9] = rgb[1]
                sv_l[10] = rgb[2]
                sv_l[11] = 0
                out_l.extend(pack_sub("DATA", bytes(sv_l)))
            elif st_l == "FNAM" and ss_l == 4:
                out_l.extend(pack_sub("FNAM", struct.pack("<f", fade)))
            else:
                out_l.extend(src_raw[sp_l : sp_l + 6 + ss_l])
            sp_l += 6 + ss_l
        return pack_record("LIGH", new_fid, bytes(out_l))

