    def make_custom_radio_receiver_acti(
        new_fid: int, edid: str, full_name: str, freq: float, src_raw: bytes
    ) -> bytes:
        a_subs = bytearray()
        a_subs.extend(pack_zstr("EDID", edid))
        sp_a = 0
        while sp_a + 6 <= len(src_raw):
            st_a = src_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_raw, sp_a + 4)[0]
            if st_a == "EDID":
                pass
            elif st_a == "FULL":
                a_subs.extend(pack_zstr("FULL", full_name))
            elif st_a == "RADR":
                a_subs.extend(pack_sub("RADR", struct.pack("<IffH", 0x00082790, freq, 1.0, 1)))
            else:
                a_subs.extend(src_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        return pack_record("ACTI", new_fid, bytes(a_subs))

    def make_custom_intercom_acti(
        new_fid: int,
        edid: str,
        full_name: str,
        attx_txt: str,
        src_raw: bytes,
        script_name: str = "V13TermNecropolisScript",
    ) -> bytes:
        a_subs = bytearray()
        a_subs.extend(pack_zstr("EDID", edid))
        if script_name:
            a_subs.extend(pack_sub("VMAD", build_simple_vmad(script_name)))
        sp_a = 0
        wrote_attx = False
        while sp_a + 6 <= len(src_raw):
            st_a = src_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_raw, sp_a + 4)[0]
            if st_a in ("EDID", "VMAD", "RADR", "ATTX"):
                pass
            elif st_a == "FULL":
                a_subs.extend(pack_zstr("FULL", full_name))
            elif st_a == "FNAM":
                a_subs.extend(src_raw[sp_a : sp_a + 6 + ss_a])
                if attx_txt and not wrote_attx:
                    a_subs.extend(pack_zstr("ATTX", attx_txt))
                    wrote_attx = True
            else:
                a_subs.extend(src_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        if attx_txt and not wrote_attx:
            a_subs.extend(pack_zstr("ATTX", attx_txt))
        return pack_record("ACTI", new_fid, bytes(a_subs))

    def make_custom_tardis_acti(
        new_fid: int,
        edid: str,
        full_name: str,
        attx_txt: str,
        model_path: str,
        src_raw: bytes,
        script_name: str = "V13TardisCallBoxScript",
        obnd_vals: tuple[int, int, int, int, int, int] = (-62, -62, 0, 62, 62, 246),
        mods_fid: int = 0,
    ) -> bytes:
        a_subs = bytearray()
        a_subs.extend(pack_zstr("EDID", edid))
        if script_name:
            a_subs.extend(pack_sub("VMAD", build_simple_vmad(script_name)))
        sp_a = 0
        wrote_attx = False
        while sp_a + 6 <= len(src_raw):
            st_a = src_raw[sp_a : sp_a + 4].decode("ascii", "ignore")
            ss_a = struct.unpack_from("<H", src_raw, sp_a + 4)[0]
            if st_a in ("EDID", "VMAD", "RADR", "ATTX", "MODT", "MODS"):
                pass
            elif st_a == "OBND":
                a_subs.extend(pack_sub("OBND", struct.pack("<6h", *obnd_vals)))
            elif st_a == "FULL":
                a_subs.extend(pack_zstr("FULL", full_name))
            elif st_a == "MODL":
                a_subs.extend(pack_zstr("MODL", model_path))
                if mods_fid != 0:
                    a_subs.extend(pack_sub("MODS", struct.pack("<I", mods_fid)))
            elif st_a == "FNAM":
                a_subs.extend(src_raw[sp_a : sp_a + 6 + ss_a])
                if attx_txt and not wrote_attx:
                    a_subs.extend(pack_zstr("ATTX", attx_txt))
                    wrote_attx = True
            else:
                a_subs.extend(src_raw[sp_a : sp_a + 6 + ss_a])
            sp_a += 6 + ss_a
        if attx_txt and not wrote_attx:
            a_subs.extend(pack_zstr("ATTX", attx_txt))
        return pack_record("ACTI", new_fid, bytes(a_subs))

