    # ZAX 1.2 Friendly Speaker Unit (0x01001509) — Stationary Protectron chassis with V13ZAX12Voice (0x0100100A)
    _, _, _, prot_raw_zax = tpl["npc_protectron"]
    zax_subs = bytearray()
    zax_subs.extend(pack_zstr("EDID", "NPC_V13_ZAX12Speaker"))
    sp_zx = 0
    wrote_snam_zx = False
    wrote_pkid_zx = False
    wrote_vtck_zx = False
    wrote_full_zx = False
    in_obte_zx = False
    while sp_zx + 6 <= len(prot_raw_zax):
        st_zx = prot_raw_zax[sp_zx : sp_zx + 4].decode("ascii", "ignore")
        ss_zx = struct.unpack_from("<H", prot_raw_zax, sp_zx + 4)[0]
        sv_zx = bytearray(prot_raw_zax[sp_zx + 6 : sp_zx + 6 + ss_zx])
        if st_zx == "OBTE":
            in_obte_zx = True
            zax_subs.extend(prot_raw_zax[sp_zx : sp_zx + 6 + ss_zx])
        elif st_zx == "STOP":
            in_obte_zx = False
            zax_subs.extend(prot_raw_zax[sp_zx : sp_zx + 6 + ss_zx])
        elif in_obte_zx:
            zax_subs.extend(prot_raw_zax[sp_zx : sp_zx + 6 + ss_zx])
        elif st_zx in ("EDID", "TPLT", "TPTA", "PKID", "VMAD", "CRIF"):
            pass
        elif st_zx == "OBND":
            zax_subs.extend(pack_sub("OBND", struct.pack("<6h", -27, -27, 0, 27, 27, 120)))
        elif st_zx == "SNAM":
            if not wrote_snam_zx:
                zax_subs.extend(pack_sub("SNAM", struct.pack("<IB", 0x01001C57, 0)))
                wrote_snam_zx = True
        elif st_zx == "VTCK":
            zax_subs.extend(pack_sub("VTCK", struct.pack("<I", 0x0100100A)))
            wrote_vtck_zx = True
        elif st_zx == "ACBS" and ss_zx >= 4:
            fl_zx = struct.unpack_from("<I", sv_zx, 0)[0]
            fl_zx = (fl_zx & ~0x00000008) | 0x00000822  # Essential + Unique + Protected
            struct.pack_into("<I", sv_zx, 0, fl_zx)
            if ss_zx >= 16:
                struct.pack_into("<H", sv_zx, 14, 0)
            zax_subs.extend(pack_sub("ACBS", bytes(sv_zx)))
        elif st_zx == "AIDT" and ss_zx >= 4:
            if not wrote_vtck_zx:
                zax_subs.extend(pack_sub("VTCK", struct.pack("<I", 0x0100100A)))
                wrote_vtck_zx = True
            sv_zx[0] = 0  # Unaggressive
            sv_zx[1] = 4  # Foolhardy
            sv_zx[3] = 0
            zax_subs.extend(pack_sub("AIDT", bytes(sv_zx)))
            if not wrote_pkid_zx:
                zax_subs.extend(pack_sub("PKID", struct.pack("<I", 0x01001050)))
                zax_subs.extend(pack_sub("PKID", struct.pack("<I", 0x0023EC8E)))
                wrote_pkid_zx = True
        elif st_zx == "FULL":
            zax_subs.extend(pack_zstr("FULL", "ZAX 1.2 — Superordenador de Investigación de West Tek"))
            zax_subs.extend(pack_zstr("SHRT", "ZAX 1.2"))
            wrote_full_zx = True
        elif st_zx == "SHRT":
            pass
        elif st_zx == "DATA" and not wrote_full_zx:
            zax_subs.extend(pack_zstr("FULL", "ZAX 1.2 — Superordenador de Investigación de West Tek"))
            zax_subs.extend(pack_zstr("SHRT", "ZAX 1.2"))
            wrote_full_zx = True
            zax_subs.extend(prot_raw_zax[sp_zx : sp_zx + 6 + ss_zx])
        else:
            zax_subs.extend(prot_raw_zax[sp_zx : sp_zx + 6 + ss_zx])
        sp_zx += 6 + ss_zx
    zax_comp = zlib.compress(bytes(zax_subs))
    shady_sands_npc_recs += pack_record(
        "NPC_", 0x01001509, struct.pack("<I", len(zax_subs)) + zax_comp, flags=0x00040000
    )

    def make_vendor_fact(fact_fid: int, edid: str, chest_refr_fid: int) -> bytes:
        f_subs = (
            pack_zstr("EDID", edid)
            + pack_sub("DATA", struct.pack("<I", 0x00004000))
            + pack_sub("CRVA", bytes.fromhex("0101000000000000000000000000000000000000"))
            + pack_sub("VEND", struct.pack("<I", 0x00022CE5))
            + pack_sub("VENC", struct.pack("<I", chest_refr_fid))
            + pack_sub("VENV", struct.pack("<HHIbbbb", 0, 24, 4096, 1, 1, 1, 0))
            + pack_sub("PLVD", struct.pack("<IIII", 12, 0, 0, 0))
        )
        return pack_record("FACT", fact_fid, f_subs)

    def make_rel_fact(fact_fid: int, edid: str, rels: list[tuple[int, int]]) -> bytes:
        f_subs = bytearray(pack_zstr("EDID", edid))
        for target_fid, combat_rel in rels:
            if target_fid == fact_fid:
                continue
            f_subs.extend(pack_sub("XNAM", struct.pack("<IiI", target_fid, 0, combat_rel)))
        f_subs.extend(pack_sub("DATA", struct.pack("<I", 0)))
        f_subs.extend(pack_sub("CRVA", bytes.fromhex("0101000000000000000000000000000000000000")))
        return pack_record("FACT", fact_fid, bytes(f_subs))

