    while sp_pk + 6 <= len(raw_pack):
        st_pk = raw_pack[sp_pk : sp_pk + 4].decode("ascii", "ignore")
        ss_pk = struct.unpack_from("<H", raw_pack, sp_pk + 4)[0]
        sv_pk = bytearray(raw_pack[sp_pk + 6 : sp_pk + 6 + ss_pk])
        if st_pk == "EDID":
            pass
        elif st_pk == "PKDT" and ss_pk == 12:
            sv_pk[4] = 0x00  # Clear MustComplete (0x02) so package holds indefinitely without falling through
            sv_pk[6] |= 0x02 # Maintain current position flag (matching DN136_StayAtCurrentPosition 0x0023EC8E)
            pack_subs.extend(pack_sub("PKDT", bytes(sv_pk)))
        elif st_pk == "PLDT":
            pack_subs.extend(pack_sub("PLDT", struct.pack("<4I", 0x0C, 0, 0, 0)))
        elif st_pk == "CNAM" and ss_pk == 1:
            cnam_bool_idx += 1
            pack_subs.extend(pack_sub("CNAM", b"\x00"))
        else:
            pack_subs.extend(raw_pack[sp_pk : sp_pk + 6 + ss_pk])
        sp_pk += 6 + ss_pk

    pack_jacoren_travel_subs = bytearray()
    pack_jacoren_travel_subs.extend(pack_zstr("EDID", "V13JacorenWaterPlantTravelPack"))
