    # 13. QUST: 0x01004000..0x01008000 + DIAL/INFO/SCEN
    def make_trda_block(resp_idx: int, sub_txt: str) -> bytes:
        trda_bytes = bytearray.fromhex("ffffffff0100000000010000ffffffffffffffff")
        trda_bytes[4] = resp_idx
        return (
            pack_sub("TRDA", bytes(trda_bytes))
            + pack_zstr("NAM1", sub_txt)
            + pack_sub("NAM2", b"\x00")
            + pack_sub("NAM3", b"\x00")
            + pack_sub("NAM4", b"\x00")
            + pack_sub("NAM9", bytes.fromhex("40b4b8279d68d801"))
        )

    def build_act_qust_and_children(
        qust_fid: int,
        qust_edid: str,
        qust_full: str,
        qust_script: str,
        qust_prio_byte: int,
        stages_list: list[tuple[int, int, str]],
        objs_list: list[tuple[int, str, int]],
        aliases_list: list[tuple[int, str, int]],
        v13_exp_door_fid: int,
        dungeon_cell_fid: int,
        dungeon_exit_fid: int,
        gree_dial_fid: int,
        gree_edid: str,
        gree_prio: float,
        gree_infos: list[dict],
        scene_defs: list[dict],
        helo_dial_fid: int | None = None,
        helo_edid: str = "",
        helo_infos: list[dict] | None = None,
        custom_topics: list[dict] | None = None,
        surface_dungeon_door_fid: int = 0x01003502,
    ) -> bytes:
        q_vmad = build_simple_vmad(qust_script)
        q_subs = bytearray()
        q_subs.extend(pack_zstr("EDID", qust_edid))
        q_subs.extend(pack_sub("VMAD", q_vmad))
        q_subs.extend(pack_zstr("FULL", qust_full))
        dnam_b = bytearray.fromhex("11003c000000000007000000")
        dnam_b[2] = qust_prio_byte
        q_subs.extend(pack_sub("DNAM", bytes(dnam_b)))
        q_subs.extend(pack_sub("XNAM", bytes.fromhex("588d1700")))
        q_subs.extend(pack_sub("NEXT", b""))

        q_subs.extend(pack_sub("INDX", struct.pack("<HBB", 10, 2, 0)))
        q_subs.extend(pack_sub("QSDT", b"\x00"))

        for stg_id, qsdt_fl, cnam_txt in stages_list:
            q_subs.extend(pack_sub("INDX", struct.pack("<HBB", stg_id, 0, 0)))
            q_subs.extend(pack_sub("QSDT", struct.pack("<B", qsdt_fl)))
            q_subs.extend(pack_zstr("CNAM", cnam_txt))

        full_aliases = sorted(
            list(aliases_list)
            + [
                (2, f"Alias_MnemosyneExtDoor_{qust_edid}", 0x01003005),
                (3, f"Alias_MnemosyneV13Door_{qust_edid}", 0x01002003),
                (4, f"Alias_CaveRouteMap_{qust_edid}", surface_dungeon_door_fid),
                (5, f"Alias_V13ExpeditionDoor_{qust_edid}", v13_exp_door_fid),
                (6, f"Alias_CaveElevatorToV13_{qust_edid}", 0x01003501),
                (7, f"Alias_DungeonExitDoor_{qust_edid}", dungeon_exit_fid),
                (8, f"Alias_MnemosyneTerminal_{qust_edid}", 0x01002D38 if qust_fid == 0x01008000 else 0x01002035),
            ],
            key=lambda x: x[0],
        )

        for obj_id, obj_txt, obj_alias in objs_list:
            q_subs.extend(pack_sub("QOBJ", struct.pack("<H", obj_id)))
            q_subs.extend(pack_sub("FNAM", struct.pack("<I", 0)))
            q_subs.extend(pack_zstr("NNAM", obj_txt))
            # Strictly 1 active QSTA per cell/worldspace so there are never duplicate markers:
            # 1) In Commonwealth (0x0000003C): Exterior Vault Entrance Door (Alias 2 = 0x01003005)
            q_subs.extend(pack_sub("QSTA", struct.pack("<III", 2, 0, 0)))
            q_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x0000003C, 1.0)))
            if qust_fid == 0x01004000 and obj_id == 15:
                # 2a) At Act I Stage 15 in Mnemosyne Bunker (0x01002000): Point FIRST to the Mainframe Terminal (Alias 8 = 0x01002035)
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 8, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002000, 1.0)))
                # Fallback if already in Vault 13 (0x01002100): Overseer Jacoren (Alias 0 = 0x01002110)
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 0, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002100, 1.0)))
                # Fallback in Southern California exterior (0x01003400): Vault 13 Surface Door (Alias 6 = 0x01003501)
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 6, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
            elif qust_fid == 0x010D1000:
                # Lost Hills T-51b Power Armor Side Quest (Hybrid: Lost Hills Bunker 0x01002B00 + Old Town Exterior 0x01003400)
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 3, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002000, 1.0)))
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 5, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002100, 1.0)))
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 4, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002200, 1.0)))
                if obj_id == 21:
                    # Path B (Rescue Initiate Lorenzo in Old Town East): exit Lost Hills (Alias 7), target Lorenzo (Alias 11) outside
                    q_subs.extend(pack_sub("QSTA", struct.pack("<III", 7, 0, 0)))
                    q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002B00, 1.0)))
                    q_subs.extend(pack_sub("QSTA", struct.pack("<III", 11, 0, 0)))
                    q_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
                else:
                    # Path A / Claim T-51b inside Lost Hills Bunker (0x01002B00): target obj_alias inside, Lost Hills Door (Alias 4) outside
                    q_subs.extend(pack_sub("QSTA", struct.pack("<III", obj_alias, 0, 0)))
                    q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002B00, 1.0)))
                    q_subs.extend(pack_sub("QSTA", struct.pack("<III", 4, 0, 0)))
                    q_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
            elif qust_fid in (0x01009500, 0x01010000, 0x01011000, 0x01012000, 0x01013000, 0x01014000, 0x01018000, 0x01019000, 0x0101A000, 0x0101D000, 0x0101E000, 0x010D2000, 0x010D3000, 0x010D4000, 0x010D5000):
                # Exterior Side Quests (Shady Sands, Junktown, The Hub, Water Merchants, Khans Pass, Lost Hills/The Glow, Boneyard, Tandi Rescue, Junktown Syndicate, Hub Syndicate, Patrick the Celt): target is in Southern California exterior (0x01003400)
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 3, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002000, 1.0)))
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 5, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002100, 1.0)))
                ext_target_alias = 4 if (qust_fid == 0x0101A000 and obj_id == 21) else obj_alias
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", ext_target_alias, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
                q_subs.extend(pack_sub("QSTA", struct.pack("<III", 7, 0, 0)))
                q_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002200, 1.0)))
                if qust_fid == 0x0101A000:
                    hub_int_alias = 10 if obj_id == 21 else 7
