        stationary_alias_npc_refs = {
            0x01002110, 0x01002153, 0x01002E11,
            0x010035A0, 0x010035A1, 0x010035A2, 0x010035A3,
            0x010035C0, 0x010035C1, 0x010035C2,
            0x010035C6, 0x010035C7, 0x010035C8,
            0x010035CB, 0x010035CC,
            0x010035D0, 0x010035D1,
            0x010035D4, 0x010035D5, 0x010035D6,
            0x010035DC, 0x010035DD, 0x010035DE,
            0x010035E6, 0x010035E7, 0x010035E8,
            0x01003570,
            0x01002B31, 0x01002B32, 0x01002B33, 0x01002B34, 0x01002B35, 0x01002B36,
            0x01003610, 0x01002815,
            0x01003621, 0x01003622, 0x01003623, 0x01003624, 0x01003625, 0x01003626, 0x01003627, 0x01003628,
            0x01002C34, 0x01003644, 0x01003646, 0x01003649, 0x0100364B,
            0x01002D11, 0x01002D12, 0x01002D32, 0x01002D33, 0x01002D34, 0x01002235, 0x01003660, 0x01003661,
        }
        next_alias_id = max((x[0] for x in full_aliases), default=-1) + 1
        q_subs.extend(pack_sub("ANAM", struct.pack("<I", next_alias_id)))
        for al_idx, al_name, al_refr in full_aliases:
            q_subs.extend(pack_sub("ALST", struct.pack("<I", al_idx)))
            q_subs.extend(pack_zstr("ALID", al_name))
            q_subs.extend(pack_sub("FNAM", struct.pack("<I", 0x0000529A)))
            q_subs.extend(pack_sub("ALFR", struct.pack("<I", al_refr)))
            if al_refr in stationary_alias_npc_refs:
                q_subs.extend(pack_sub("ALPC", struct.pack("<I", 0x01001050)))
            q_subs.extend(pack_sub("VTCK", struct.pack("<I", 0)))
            q_subs.extend(pack_sub("ALED", b""))

        q_rec = pack_record("QUST", qust_fid, bytes(q_subs))

        g_dial_subs = (
            pack_zstr("EDID", gree_edid)
            + pack_zstr("FULL", "Greetings")
            + pack_sub("PNAM", struct.pack("<f", gree_prio))
            + pack_sub("QNAM", struct.pack("<I", qust_fid))
            + pack_sub("DATA", bytes.fromhex("01077600"))
            + pack_sub("SNAM", b"GREE")
            + pack_sub("TIFC", struct.pack("<I", len(gree_infos)))
        )
        g_dial_rec = pack_record("DIAL", gree_dial_fid, g_dial_subs)

        g_info_recs = bytearray()
        for gdef in gree_infos:
            enam_val = gdef.get("enam_flags", 0x00000000)
            spk_fid = gdef.get("speaker_fid", 0x01001200)
            isubs = bytearray()
            isubs.extend(pack_sub("ENAM", struct.pack("<I", enam_val)))
            isubs.extend(pack_sub("PNAM", struct.pack("<I", gdef["prev_fid"])))
            for r_idx, (sub_txt, _tts_txt) in enumerate(gdef["responses"], 1):
                isubs.extend(make_trda_block(r_idx, sub_txt))
            for op_b, stg_f in gdef["stage_conds"]:
                isubs.extend(pack_sub("CTDA", make_ctda_getstage(op_b, stg_f, qust_fid)))
            for op_b, stg_f, other_qfid in gdef.get("other_quest_conds", []):
                isubs.extend(pack_sub("CTDA", make_ctda_getstage(op_b, stg_f, other_qfid)))
            for ect in gdef.get("extra_ctdas", []):
                if ect[0] == "getstagedone":
                    isubs.extend(pack_sub("CTDA", make_ctda_getstagedone(ect[1], int(ect[2]), bool(ect[3]))))
            isubs.extend(pack_sub("CTDA", make_ctda_getisid(spk_fid)))
            isubs.extend(pack_sub("ANAM", struct.pack("<I", spk_fid)))
            if gdef["tsce_fid"] is not None:
                isubs.extend(pack_sub("TSCE", struct.pack("<I", gdef["tsce_fid"])))
            if gdef["intv_phase"] is not None:
                isubs.extend(pack_sub("INTV", struct.pack("<I", gdef["intv_phase"])))
            if gdef["tiqs_stage"] is not None:
                isubs.extend(pack_sub("TIQS", struct.pack("<HH", 0xFFFF, gdef["tiqs_stage"])))
            isubs.extend(pack_zstr("NAM0", gdef["nam0_phase"]))
            isubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
            g_info_recs.extend(pack_record("INFO", gdef["info_fid"], bytes(isubs)))

        g_dial_grup = (
            b"GRUP"
            + struct.pack("<IIIII", 24 + len(g_info_recs), gree_dial_fid, 7, 0, 0)
            + bytes(g_info_recs)
        )

        h_dial_block = b""
        if helo_dial_fid is not None and helo_infos:
            h_dial_subs = (
                pack_zstr("EDID", helo_edid)
                + pack_sub("PNAM", struct.pack("<f", gree_prio))
                + pack_sub("QNAM", struct.pack("<I", qust_fid))
                + pack_sub("DATA", bytes.fromhex("00075200"))
                + pack_sub("SNAM", b"HELO")
                + pack_sub("TIFC", struct.pack("<I", len(helo_infos)))
            )
            h_dial_rec = pack_record("DIAL", helo_dial_fid, h_dial_subs)
            h_info_recs = bytearray()
            for hdef in helo_infos:
                h_spk = hdef["speaker_fid"]
                hsubs = bytearray()
                hsubs.extend(pack_sub("ENAM", struct.pack("<I", hdef.get("enam_flags", 0x00000004))))
                hsubs.extend(pack_sub("PNAM", struct.pack("<I", hdef["prev_fid"])))
                for r_idx, (sub_txt, _tts_txt) in enumerate(hdef["responses"], 1):
                    hsubs.extend(make_trda_block(r_idx, sub_txt))
                for op_b, stg_f in hdef.get("stage_conds", []):
                    hsubs.extend(pack_sub("CTDA", make_ctda_getstage(op_b, stg_f, qust_fid)))
                for op_b, stg_f, other_qfid in hdef.get("other_quest_conds", []):
                    hsubs.extend(pack_sub("CTDA", make_ctda_getstage(op_b, stg_f, other_qfid)))
                hsubs.extend(pack_sub("CTDA", make_ctda_getisid(h_spk)))
                hsubs.extend(pack_sub("ANAM", struct.pack("<I", h_spk)))
                hsubs.extend(pack_zstr("NAM0", ""))
                hsubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
                h_info_recs.extend(pack_record("INFO", hdef["info_fid"], bytes(hsubs)))
            h_dial_grup = (
                b"GRUP"
                + struct.pack("<IIIII", 24 + len(h_info_recs), helo_dial_fid, 7, 0, 0)
                + bytes(h_info_recs)
            )
            stop_dial_fid = 0x01004003
            stop_dial_subs = (
                pack_zstr("EDID", "V13Act1ResidentStopTopic")
                + pack_sub("PNAM", struct.pack("<f", 100.0))
                + pack_sub("QNAM", struct.pack("<I", qust_fid))
                + pack_sub("DATA", bytes.fromhex("00000000"))
                + pack_sub("SNAM", b"CUST")
                + pack_sub("TIFC", struct.pack("<I", 1))
            )
            stop_dial_rec = pack_record("DIAL", stop_dial_fid, stop_dial_subs)
            stop_info_subs = (
                pack_sub("ENAM", struct.pack("<I", 0x00000004))
                + pack_sub("PNAM", struct.pack("<I", 0))
                + make_trda_block(1, "")
                + pack_zstr("NAM0", "")
                + pack_sub("INAM", struct.pack("<I", 1))
            )
            stop_info_rec = pack_record("INFO", 0x0100407F, stop_info_subs)
            stop_dial_grup = (
                b"GRUP"
                + struct.pack("<IIIII", 24 + len(stop_info_rec), stop_dial_fid, 7, 0, 0)
                + stop_info_rec
            )
            h_dial_block = h_dial_rec + h_dial_grup + stop_dial_rec + stop_dial_grup

        s_dials_bytes = bytearray()
        s_recs_bytes = bytearray()

        def make_scene_dial_and_grup(
            dial_fid: int, info_rec_bytes: bytes, num_infos: int = 1
        ) -> bytes:
            d_subs = (
                pack_sub("PNAM", struct.pack("<f", 50.0))
                + pack_sub("QNAM", struct.pack("<I", qust_fid))
                + pack_sub("DATA", bytes.fromhex("00020e00"))
                + pack_sub("SNAM", b"SCEN")
                + pack_sub("TIFC", struct.pack("<I", num_infos))
            )
            d_rec = pack_record("DIAL", dial_fid, d_subs, fver=48)
            d_grup = (
                b"GRUP"
                + struct.pack("<IIIII", 24 + len(info_rec_bytes), dial_fid, 7, 0, 0)
                + info_rec_bytes
            )
            return d_rec + d_grup

        for sdef in scene_defs:
            scen_fid = sdef["scen_fid"]
            scen_subs = bytearray()
            scen_subs.extend(pack_zstr("EDID", sdef["edid"]))
            scen_subs.extend(pack_sub("FNAM", bytes.fromhex("24100000")))

            for ph_name in sdef["phases"]:
                scen_subs.extend(pack_sub("HNAM", b""))
                scen_subs.extend(pack_zstr("NAM0", ph_name))
                scen_subs.extend(pack_sub("NEXT", b""))
                scen_subs.extend(pack_sub("NEXT", b""))
                scen_subs.extend(pack_sub("WNAM", struct.pack("<I", 450)))
                scen_subs.extend(pack_sub("HNAM", b""))

            act_alid = sdef.get("actor_alias_id", 0)
            scen_subs.extend(pack_sub("ALID", struct.pack("<I", act_alid)))
            scen_subs.extend(pack_sub("LNAM", struct.pack("<I", sdef.get("lnam_flags", 0x00000004))))
            scen_subs.extend(pack_sub("DNAM", struct.pack("<I", 0x0000000A)))

            max_act_idx = 1
            for act in sdef["actions"]:
                a_idx = act["action_idx"]
                if a_idx > max_act_idx:
                    max_act_idx = a_idx
                ph_idx = act["phase_idx"]
                opts = act["options"]

                scen_subs.extend(pack_sub("ANAM", struct.pack("<H", 3)))
                scen_subs.extend(pack_sub("NAM0", b"\x00"))
                scen_subs.extend(pack_sub("ALID", struct.pack("<I", act_alid)))
                scen_subs.extend(pack_sub("INAM", struct.pack("<I", a_idx)))
                scen_subs.extend(pack_sub("FNAM", bytes.fromhex("00802200")))
                scen_subs.extend(pack_sub("SNAM", struct.pack("<I", ph_idx)))
                scen_subs.extend(pack_sub("ENAM", struct.pack("<I", ph_idx)))
                scen_subs.extend(pack_sub("PTOP", struct.pack("<I", opts[0]["p_dial"])))
                scen_subs.extend(pack_sub("NTOP", struct.pack("<I", opts[1]["p_dial"])))
                scen_subs.extend(pack_sub("NETO", struct.pack("<I", opts[2]["p_dial"])))
                scen_subs.extend(pack_sub("QTOP", struct.pack("<I", opts[3]["p_dial"])))
                scen_subs.extend(pack_sub("NPOT", struct.pack("<I", opts[0]["n_dial"])))
                scen_subs.extend(pack_sub("NNGT", struct.pack("<I", opts[1]["n_dial"])))
                scen_subs.extend(pack_sub("NNUT", struct.pack("<I", opts[2]["n_dial"])))
                scen_subs.extend(pack_sub("NQUT", struct.pack("<I", opts[3]["n_dial"])))
                scen_subs.extend(pack_sub("DTGT", struct.pack("<I", act_alid)))
                scen_subs.extend(pack_sub("ANAM", b""))

                for opt in opts:
                    p_stage_val = opt.get("p_tiqs_stage")
                    if (
                        p_stage_val is not None
                        and p_stage_val == opt.get("tiqs_stage")
                        and not opt.get("force_p_tiqs")
                    ):
                        p_stage_val = None
                    p_tiqs_bytes = (
                        pack_sub("TIQS", struct.pack("<HH", 0xFFFF, p_stage_val))
                        if p_stage_val is not None
                        else b""
                    )
                    if "p_info_f" in opt:
                        pm_isubs = (
                            pack_sub("ENAM", struct.pack("<I", 0))
                            + pack_sub("PNAM", struct.pack("<I", 0))
                            + make_trda_block(1, opt["p_sub"])
                            + pack_sub("CTDA", make_ctda_player_sex(0))
                            + p_tiqs_bytes
                            + pack_zstr("RNAM", opt["rnam"])
                            + pack_sub("NAM0", b"\x00")
                            + pack_sub("INAM", struct.pack("<I", 1))
                        )
                        pf_isubs = (
                            pack_sub("ENAM", struct.pack("<I", 0))
                            + pack_sub("PNAM", struct.pack("<I", opt["p_info"]))
                            + make_trda_block(1, opt["p_sub_f"])
                            + pack_sub("CTDA", make_ctda_player_sex(1))
                            + p_tiqs_bytes
                            + pack_zstr("RNAM", opt["rnam_f"])
                            + pack_sub("NAM0", b"\x00")
                            + pack_sub("INAM", struct.pack("<I", 1))
                        )
                        p_info_rec = pack_record(
                            "INFO", opt["p_info"], pm_isubs
                        ) + pack_record("INFO", opt["p_info_f"], pf_isubs)
                        s_dials_bytes.extend(
                            make_scene_dial_and_grup(opt["p_dial"], p_info_rec, num_infos=2)
                        )
                    else:
                        p_isubs = bytearray()
                        p_isubs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
                        p_isubs.extend(pack_sub("PNAM", struct.pack("<I", 0)))
                        p_isubs.extend(make_trda_block(1, opt["p_sub"]))
                        for ct_kind, ct_op, ct_form, ct_val in opt.get("p_ctdas", []):
                            if ct_kind == "get_stage_done":
                                p_isubs.extend(
                                    pack_sub("CTDA", make_ctda_getstagedone(ct_form, int(ct_val), bool(ct_op)))
                                )
                        p_isubs.extend(p_tiqs_bytes)
                        p_isubs.extend(pack_zstr("RNAM", opt["rnam"]))
                        p_isubs.extend(pack_sub("NAM0", b"\x00"))
                        p_isubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
                        p_info_rec = pack_record("INFO", opt["p_info"], bytes(p_isubs))
                        if "p_fail_info" in opt:
                            pf_alt_isubs = (
                                pack_sub("ENAM", struct.pack("<I", 0))
                                + pack_sub("PNAM", struct.pack("<I", opt["p_info"]))
                                + make_trda_block(1, opt["p_fail_sub"])
                                + p_tiqs_bytes
                                + pack_zstr("RNAM", opt["p_fail_rnam"])
                                + pack_sub("NAM0", b"\x00")
                                + pack_sub("INAM", struct.pack("<I", 1))
                            )
                            pf_alt_rec = pack_record("INFO", opt["p_fail_info"], pf_alt_isubs)
                            s_dials_bytes.extend(
                                make_scene_dial_and_grup(
                                    opt["p_dial"], p_info_rec + pf_alt_rec, num_infos=2
                                )
                            )
                        else:
                            s_dials_bytes.extend(
                                make_scene_dial_and_grup(opt["p_dial"], p_info_rec, num_infos=1)
                            )

                    n_isubs = bytearray()
                    n_isubs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
                    n_isubs.extend(pack_sub("PNAM", struct.pack("<I", 0)))
                    for r_idx, (sub_txt, _tts_txt) in enumerate(opt["n_responses"], 1):
                        n_isubs.extend(make_trda_block(r_idx, sub_txt))
                    for ct_kind, ct_op, ct_form, ct_val in opt.get("n_ctdas", []):
                        if ct_kind == "player_av":
                            n_isubs.extend(
                                pack_sub("CTDA", make_ctda_player_getvalue(ct_op, ct_form, ct_val))
                            )
                        elif ct_kind == "player_perk":
                            n_isubs.extend(
                                pack_sub("CTDA", make_ctda_player_hasperk(ct_op, ct_form, ct_val))
                            )
                        elif ct_kind == "player_item":
                            n_isubs.extend(
                                pack_sub("CTDA", make_ctda_player_getitemcount(ct_op, ct_form, ct_val))
                            )
                        elif ct_kind == "get_stage_done":
                            n_isubs.extend(
                                pack_sub("CTDA", make_ctda_getstagedone(ct_form, int(ct_val), bool(ct_op)))
                            )
                    if "loop_phase" in opt:
                        l_idx, l_name = opt["loop_phase"]
                        n_isubs.extend(pack_sub("TSCE", struct.pack("<I", scen_fid)))
                        if l_idx > 0:
                            n_isubs.extend(pack_sub("INTV", struct.pack("<I", l_idx)))
                        if opt.get("tiqs_stage") is not None:
                            n_isubs.extend(
                                pack_sub("TIQS", struct.pack("<HH", 0xFFFF, opt["tiqs_stage"]))
                            )
                        n_isubs.extend(pack_zstr("NAM0", l_name))
                    else:
                        if opt.get("tiqs_stage") is not None:
                            n_isubs.extend(
                                pack_sub("TIQS", struct.pack("<HH", 0xFFFF, opt["tiqs_stage"]))
                            )
                        n_isubs.extend(pack_sub("NAM0", b"\x00"))
                    n_isubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
                    n_info_rec = pack_record("INFO", opt["n_info"], bytes(n_isubs))
                    if "n_fail_info" in opt:
                        nf_isubs = bytearray()
                        nf_isubs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
                        nf_isubs.extend(pack_sub("PNAM", struct.pack("<I", opt["n_info"])))
                        for r_idx, (sub_txt, _tts_txt) in enumerate(opt["n_fail_responses"], 1):
                            nf_isubs.extend(make_trda_block(r_idx, sub_txt))
                        if "n_fail_loop_phase" in opt:
                            fl_idx, fl_name = opt["n_fail_loop_phase"]
                            nf_isubs.extend(pack_sub("TSCE", struct.pack("<I", scen_fid)))
                            if fl_idx > 0:
                                nf_isubs.extend(pack_sub("INTV", struct.pack("<I", fl_idx)))
                            if "n_fail_tiqs_stage" in opt:
                                nf_isubs.extend(
                                    pack_sub(
                                        "TIQS", struct.pack("<HH", 0xFFFF, opt["n_fail_tiqs_stage"])
                                    )
                                )
                            nf_isubs.extend(pack_zstr("NAM0", fl_name))
                        else:
                            if "n_fail_tiqs_stage" in opt:
                                nf_isubs.extend(
                                    pack_sub(
                                        "TIQS", struct.pack("<HH", 0xFFFF, opt["n_fail_tiqs_stage"])
                                    )
                                )
                            nf_isubs.extend(pack_sub("NAM0", b"\x00"))
                        nf_isubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
                        nf_info_rec = pack_record("INFO", opt["n_fail_info"], bytes(nf_isubs))
                        s_dials_bytes.extend(
                            make_scene_dial_and_grup(
                                opt["n_dial"], n_info_rec + nf_info_rec, num_infos=2
                            )
                        )
                    else:
                        s_dials_bytes.extend(
                            make_scene_dial_and_grup(opt["n_dial"], n_info_rec, num_infos=1)
                        )

            if "intro_npc_action" in sdef:
                in_act = sdef["intro_npc_action"]
                max_act_idx += 1
                scen_subs.extend(pack_sub("ANAM", struct.pack("<H", 0)))
                scen_subs.extend(pack_sub("NAM0", b"\x00"))
                scen_subs.extend(pack_sub("ALID", struct.pack("<I", act_alid)))
                scen_subs.extend(pack_sub("INAM", struct.pack("<I", max_act_idx)))
                scen_subs.extend(pack_sub("FNAM", bytes.fromhex("00800200")))
                scen_subs.extend(pack_sub("SNAM", struct.pack("<I", 0)))
                scen_subs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
                scen_subs.extend(pack_sub("DATA", struct.pack("<I", in_act["dial_fid"])))
                scen_subs.extend(pack_sub("DMAX", struct.pack("<f", 10.0)))
                scen_subs.extend(pack_sub("DMIN", struct.pack("<f", 1.0)))
                scen_subs.extend(pack_sub("HTID", struct.pack("<I", 0xFFFFFFFF)))
                scen_subs.extend(pack_sub("ANAM", b""))
                in_isubs = bytearray()
                in_isubs.extend(pack_sub("ENAM", struct.pack("<I", 0)))
                in_isubs.extend(pack_sub("PNAM", struct.pack("<I", 0)))
                in_isubs.extend(make_trda_block(1, in_act["sub"]))
                if "speaker_fid" in in_act:
                    in_isubs.extend(pack_sub("ANAM", struct.pack("<I", in_act["speaker_fid"])))
                in_isubs.extend(pack_sub("NAM0", b"\x00"))
                in_isubs.extend(pack_sub("INAM", struct.pack("<I", 1)))
                in_info_rec = pack_record("INFO", in_act["info_fid"], bytes(in_isubs))
                s_dials_bytes.extend(
                    make_scene_dial_and_grup(in_act["dial_fid"], in_info_rec, num_infos=1)
                )

            if "scene_package_fid" in sdef:
                max_act_idx += 1
                scen_subs.extend(pack_sub("ANAM", struct.pack("<H", 1)))
                scen_subs.extend(pack_sub("NAM0", b"\x00"))
                scen_subs.extend(pack_sub("ALID", struct.pack("<I", act_alid)))
                scen_subs.extend(pack_sub("INAM", struct.pack("<I", max_act_idx)))
                scen_subs.extend(pack_sub("SNAM", struct.pack("<I", 0)))
                scen_subs.extend(pack_sub("ENAM", struct.pack("<I", len(sdef["phases"]) - 1)))
                scen_subs.extend(pack_sub("PNAM", struct.pack("<I", sdef["scene_package_fid"])))
                scen_subs.extend(pack_sub("ANAM", b""))

            if "phase_package_action" in sdef:
                ph_start, ph_end, ph_pack_fid = sdef["phase_package_action"]
                max_act_idx += 1
                scen_subs.extend(pack_sub("ANAM", struct.pack("<H", 1)))
                scen_subs.extend(pack_sub("NAM0", b"\x00"))
                scen_subs.extend(pack_sub("ALID", struct.pack("<I", act_alid)))
                scen_subs.extend(pack_sub("INAM", struct.pack("<I", max_act_idx)))
                scen_subs.extend(pack_sub("SNAM", struct.pack("<I", ph_start)))
                scen_subs.extend(pack_sub("ENAM", struct.pack("<I", ph_end)))
                scen_subs.extend(pack_sub("PNAM", struct.pack("<I", ph_pack_fid)))
                scen_subs.extend(pack_sub("ANAM", b""))

            scen_subs.extend(pack_sub("PNAM", struct.pack("<I", qust_fid)))
            scen_subs.extend(pack_sub("INAM", struct.pack("<I", max_act_idx)))
            scen_subs.extend(pack_sub("VNAM", struct.pack("<4I", 3, 3, 3, 3)))
            scen_subs.extend(pack_sub("XNAM", struct.pack("<I", 0)))
            s_recs_bytes.extend(
                pack_record("SCEN", scen_fid, bytes(scen_subs), fver=119, v2=9)
            )

        cust_dials_bytes = bytearray()
        if custom_topics:
            for cdef in custom_topics:
                c_dial_fid = cdef["dial_fid"]
                c_dial_subs = (
                    pack_zstr("EDID", cdef["edid"])
                    + pack_sub("PNAM", struct.pack("<f", 95.0))
                    + pack_sub("QNAM", struct.pack("<I", qust_fid))
                    + pack_sub("DATA", bytes.fromhex("00000000"))
                    + pack_sub("SNAM", b"CUST")
                    + pack_sub("TIFC", struct.pack("<I", 1))
                )
                c_dial_rec = pack_record("DIAL", c_dial_fid, c_dial_subs)
                c_spk = cdef["speaker_fid"]
                c_info_subs = (
                    pack_sub("ENAM", struct.pack("<I", 0x00000000))
                    + pack_sub("PNAM", struct.pack("<I", 0))
                    + make_trda_block(1, cdef["sub"])
                    + pack_sub("CTDA", make_ctda_getisid(c_spk))
                    + pack_sub("ANAM", struct.pack("<I", c_spk))
                    + pack_zstr("NAM0", "")
                    + pack_sub("INAM", struct.pack("<I", 1))
                )
                c_info_rec = pack_record("INFO", cdef["info_fid"], c_info_subs)
                c_dial_grup = (
                    b"GRUP"
                    + struct.pack("<IIIII", 24 + len(c_info_rec), c_dial_fid, 7, 0, 0)
                    + c_info_rec
                )
                cust_dials_bytes.extend(c_dial_rec + c_dial_grup)

        q_children = (
            g_dial_rec
            + g_dial_grup
            + h_dial_block
            + bytes(cust_dials_bytes)
            + bytes(s_dials_bytes)
            + bytes(s_recs_bytes)
        )
        q_children_grup = (
            b"GRUP"
            + struct.pack("<IIIII", 24 + len(q_children), qust_fid, 10, 0, 0)
            + q_children
        )
        return q_rec + q_children_grup

