    def build_giant_footprint_qust_record() -> bytes:
        gf_fid = 0x0101B000
        gf_edid = "V13SideQuestGiantFootprint"
        gf_full = "Encuentro Especial: La Huella Gigante de Godzilla"
        gf_vmad = build_simple_vmad("V13SideQuestTardisScript")
        gf_subs = bytearray()
        gf_subs.extend(pack_zstr("EDID", gf_edid))
        gf_subs.extend(pack_sub("VMAD", gf_vmad))
        gf_subs.extend(pack_zstr("FULL", gf_full))
        dnam_gf = bytearray.fromhex("110048000000000007000000")
        gf_subs.extend(pack_sub("DNAM", bytes(dnam_gf)))
        gf_subs.extend(pack_sub("XNAM", bytes.fromhex("588d1700")))
        gf_subs.extend(pack_sub("NEXT", b""))
        gf_subs.extend(pack_sub("INDX", struct.pack("<HBB", 10, 2, 0)))
        gf_subs.extend(pack_sub("QSDT", b"\x00"))
        for stg_id, qsdt_fl, cnam_txt in [
            (
                20,
                0,
                "Al norte de Arenas Sombrías hay una anomalía: una descomunal huella de reptil de tres dedos con un cuerpo aplastado en el centro.",
            ),
            (
                25,
                0,
                "Junto a la Huella Gigante yace un viajero aplastado que portaba un RobCo Stealth Boy 3001 experimental. Registra el cuerpo.",
            ),
            (
                30,
                1,
                "Has examinado la Huella Gigante y recuperado el RobCo Stealth Boy 3001 y suministros del viajero.",
            ),
        ]:
            gf_subs.extend(pack_sub("INDX", struct.pack("<HBB", stg_id, 0, 0)))
            gf_subs.extend(pack_sub("QSDT", struct.pack("<B", qsdt_fl)))
            gf_subs.extend(pack_zstr("CNAM", cnam_txt))

        for obj_id, obj_txt, obj_alias in [
            (20, "Examina la Huella Gigante al norte de Arenas Sombrías", 0),
            (25, "Recoge el RobCo Stealth Boy 3001 del viajero", 1),
        ]:
            gf_subs.extend(pack_sub("QOBJ", struct.pack("<H", obj_id)))
            gf_subs.extend(pack_sub("FNAM", struct.pack("<I", 0)))
            gf_subs.extend(pack_zstr("NNAM", obj_txt))
            gf_subs.extend(pack_sub("QSTA", struct.pack("<III", 2, 0, 0)))
            gf_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x0000003C, 1.0)))
            gf_subs.extend(pack_sub("QSTA", struct.pack("<III", 3, 0, 0)))
            gf_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002000, 1.0)))
            gf_subs.extend(pack_sub("QSTA", struct.pack("<III", 5, 0, 0)))
            gf_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002100, 1.0)))
            gf_subs.extend(pack_sub("QSTA", struct.pack("<III", obj_alias, 0, 0)))
            gf_subs.extend(pack_sub("CTDA", make_ctda_player_inworldspace(0x01003400, 1.0)))
            gf_subs.extend(pack_sub("QSTA", struct.pack("<III", 7, 0, 0)))
            gf_subs.extend(pack_sub("CTDA", make_ctda_player_incell(0x01002200, 1.0)))

        gf_aliases = [
            (0, "Alias_GiantFootprint", 0x01003561),
            (1, "Alias_FootprintVictim", 0x01003560),
            (2, "Alias_MnemosyneExtDoor_V13SideQuestGiantFootprint", 0x01003005),
            (3, "Alias_MnemosyneV13Door_V13SideQuestGiantFootprint", 0x01002003),
            (4, "Alias_CaveRouteMap_V13SideQuestGiantFootprint", 0x0100352B),
            (5, "Alias_V13ExpeditionDoor_V13SideQuestGiantFootprint", 0x01002101),
            (6, "Alias_CaveElevatorToV13_V13SideQuestGiantFootprint", 0x01003501),
            (7, "Alias_DungeonExitDoor_V13SideQuestGiantFootprint", 0x01002206),
            (8, "Alias_MnemosyneTerminal_V13SideQuestGiantFootprint", 0x01002035),
            (9, "Alias_GiantFootprintDeskTerm", 0x01003562),
        ]
        gf_subs.extend(pack_sub("ANAM", struct.pack("<I", 10)))
        for al_idx, al_name, al_refr in gf_aliases:
            gf_subs.extend(pack_sub("ALST", struct.pack("<I", al_idx)))
            gf_subs.extend(pack_zstr("ALID", al_name))
            gf_subs.extend(pack_sub("FNAM", struct.pack("<I", 0x0000529A)))
            gf_subs.extend(pack_sub("ALFR", struct.pack("<I", al_refr)))
            gf_subs.extend(pack_sub("VTCK", struct.pack("<I", 0)))
            gf_subs.extend(pack_sub("ALED", b""))
        return pack_record("QUST", gf_fid, bytes(gf_subs))

