    # ==============================================================================
    # 15B. CLMT 0x010033FF + WRLD 0x01003400 (V13SouthernCaliforniaWorld — "Sur de California (2161)")
    #      Full 64-Cell 3D Open-World Exterior (-16384..+16384 x -16384..+16384) with
    #      seamless 3D LAND topography matching Fallout 1's Southern California map 1:1,
    #      surface bunker entrances, Shady Sands settlement, Bakersfield/Necropolis
    #      open-air ruined city streets, highways, wasteland creatures, and fast travel!
    # ==============================================================================
    clmt_v13_subs = bytearray(pack_zstr("EDID", "V13CaliforniaAridClimate"))
    clmt_v13_subs.extend(
        pack_sub(
            "WLST",
            struct.pack(
                "<9I",
                0x001D670E, 65, 0,  # CommonwealthClear (65%)
                0x0002B52A, 30, 0,  # CommonwealthPolluted (30%)
                0x001C3D5E, 5, 0,   # CommonwealthGS arid haze (5%)
            ),
        )
    )
    _clmt_raw = tpl["clmt_default"][3]
