    _protected_hub_xy = [
        (-7000.0, 33000.0), (-6400.0, 32940.0), (-18000.0, 33500.0), (6500.0, 23500.0),
        (7500.0, 5500.0), (-3500.0, -13500.0), (-3500.0, -11400.0), (-5400.0, -11800.0),
        (-5400.0, -15450.0), (-3500.0, -15750.0), (-1650.0, -13000.0), (-1650.0, -14500.0),
        (2800.0, -13500.0), (21500.0, 18500.0),
        (-24500.0, -7500.0), (-5600.0, -32200.0), (-19500.0, -31500.0), (33500.0, 13500.0),
        (28000.0, -8000.0), (33500.0, -7000.0), (25500.0, -11500.0), (29000.0, -2000.0),
        (31500.0, -31500.0), (31500.0, -33520.0), (20500.0, 5000.0), (5500.0, -4800.0),
        (-31500.0, 16500.0), (-20000.0, 19500.0), (10500.0, -15500.0), (20000.0, -33500.0),
        (28500.0, 4680.0), (-11430.0, -23420.0), (-24420.0, 10580.0), (-11620.0, -5420.0),
        (-30720.0, 2500.0),
    ]
    for _ec_fid_chk, _ec_b_chk, (_ecx_chk, _ecy_chk), _ in v13_exterior_creatures:
        if 0x01003700 <= _ec_fid_chk <= 0x0100372B:
            assert _ecx_chk >= _coastline_x(_ecy_chk) + 600.0, f"Creature 0x{_ec_fid_chk:08X} too close to coast"
            for _hx_chk, _hy_chk in _protected_hub_xy:
                assert math.hypot(_ecx_chk - _hx_chk, _ecy_chk - _hy_chk) >= 4500.0, (
                    f"Creature 0x{_ec_fid_chk:08X} violates 4500u buffer near ({_hx_chk}, {_hy_chk})"
                )
    for ec_fid, ec_base, (ecx, ecy), ecrz in v13_exterior_creatures:
        ecz = round(global_california_height(ecx, ecy) / 8.0) * 8.0 + 6.0
        ec_subs = (
            pack_sub("NAME", struct.pack("<I", ec_base))
            + pack_sub("DATA", struct.pack("<6f", ecx, ecy, ecz, 0.0, 0.0, ecrz))
        )
        ec_flags = 0x00000C00 if ec_fid == 0x0100358D else 0x00000400
        v13_wrld_pers_refs.extend(pack_record("ACHR", ec_fid, ec_subs, flags=ec_flags))

