    def add_ext_loot_container_ref(
        base_fid: int,
        wx: float,
        wy: float,
        wz: float,
        rz: float = 0.0,
        lock_level: int = 0,
    ) -> None:
        nonlocal next_ext_ref_fid
        cx = max(CELL_MIN, min(CELL_MAX, int(math.floor(wx / 4096.0))))
        cy = max(CELL_MIN, min(CELL_MAX, int(math.floor(wy / 4096.0))))
        c_subs = bytearray(pack_sub("NAME", struct.pack("<I", base_fid)))
        if lock_level > 0:
            c_subs.extend(pack_sub("XLOC", struct.pack("<B15x", lock_level)))
        c_subs.extend(pack_sub("DATA", struct.pack("<6f", wx, wy, wz, 0.0, 0.0, rz)))
        ext_cell_temp_refs[(cx, cy)].extend(pack_record("REFR", next_ext_ref_fid, bytes(c_subs)))
        next_ext_ref_fid += 1

