        # Extract and clean MetalTrapdoorLadder01.nif -> hide horizontal RV door panel (MetalTrapdoorLadder01:13)
        # and extend top/bottom steel ladder rail tips (MetalTrapdoorLadder01:24) so the vertical ladder spans floor to ceiling cleanly
        f.seek(name_tbl_ofs)
        lad01_idx = None
        for i in range(num_files):
            nlen = struct.unpack("<H", f.read(2))[0]
            name = f.read(nlen).decode("utf-8", "replace").lower().replace("/", "\\")
